import{_ as p,W as o,s as r,u as d,ah as l,I as i,w as a,Z as n,A as t}from"./chunks/framework.DYeiaKBS.js";import"./chunks/theme.DJBbXXYU.js";const v=JSON.parse('{"title":"基础：在 Linux 终端中删除文件和文件夹 | LCTT x X-CMD","titleTemplate":false,"description":"基础：在 Linux 终端中删除文件和文件夹 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基础：在 Linux 终端中删除文件和文件夹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基础：在 Linux 终端中删除文件和文件夹 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210807 Remove files and folders in the Linux terminal","title":"基础：在 Linux 终端中删除文件和文件夹","tag":"202108"},"relativePath":"202108/20210807 Remove files and folders in the Linux terminal.md","filePath":"[post].md"}'),u={name:"202108/20210807 Remove files and folders in the Linux terminal.md"};function m(h,e,c,g,f,x){const s=o("Link");return d(),r("div",null,[e[20]||(e[20]=l(`<h1 id="基础-在-linux-终端中删除文件和文件夹" tabindex="-1">基础：在 Linux 终端中删除文件和文件夹 <a class="header-anchor" href="#基础-在-linux-终端中删除文件和文件夹" aria-label="Permalink to 基础：在 Linux 终端中删除文件和文件夹">​</a></h1><blockquote><p>本教程讲述了如何在 Linux 终端中安全地删除文件和文件夹。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/16/110943z9boolgobdlyoiyo.jpg" alt=""></p><p>要想使用图形化界面删除计算机上的文件，你可能会直接将文件或文件夹拖拽到 “垃圾箱” 或 “回收站”。或者你也可以选择要删除的文件或文件夹，右键单击并选择 <strong>删除</strong>。</p><p>而在终端中删除文件或文件夹时并没有垃圾箱一说（至少默认情况下没有）。在图形化桌面上，<code>Trash</code>（即垃圾箱文件夹）是一个受保护的目录，保护机制可以防止用户不小心将该目录删除，或将其从默认位置移动从而导致找不到它。Trash 本质不过是一个被高度管理的文件夹，因此你可以创建自己的 Trash 文件夹以在终端中使用。</p><h3 id="为终端设置一个垃圾箱" tabindex="-1">为终端设置一个垃圾箱 <a class="header-anchor" href="#为终端设置一个垃圾箱" aria-label="Permalink to 为终端设置一个垃圾箱">​</a></h3><p>在家目录中创建一个名为 <code>Trash</code> 的目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkdir ~/Trash</span></span></code></pre></div><h3 id="删除文件" tabindex="-1">删除文件 <a class="header-anchor" href="#删除文件" aria-label="Permalink to 删除文件">​</a></h3><p>要删除文件或文件夹时，使用 <code>mv</code> 命令将文件或文件夹移至 <code>Trash</code> 中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mv example.txt ~/Trash</span></span></code></pre></div><h3 id="永久删除文件或文件夹" tabindex="-1">永久删除文件或文件夹 <a class="header-anchor" href="#永久删除文件或文件夹" aria-label="Permalink to 永久删除文件或文件夹">​</a></h3><p>当你准备从系统中永久删除某个文件或文件夹时，可以使用 <code>rm</code> 命令清除垃圾箱文件夹中的所有数据。通过将 <code>rm</code> 命令指向星号（<code>*</code>），可以删除 <code>Trash</code> 文件夹内的所有文件和文件夹，而不会删除 <code>Trash</code> 文件夹本身。因为用户可以方便且自由地创建目录，所以即使不小心删除了 <code>Trash</code> 文件夹，你也可以再次新建一个。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rm --recursive ~/Trash/*</span></span></code></pre></div><h3 id="删除空目录" tabindex="-1">删除空目录 <a class="header-anchor" href="#删除空目录" aria-label="Permalink to 删除空目录">​</a></h3><p>删除空目录有一个专门的命令 <code>rmdir</code>，它只能用来删除空目录，从而保护你免受递归删除错误的影响。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mkdir full</span></span>
<span class="line"><span>$ touch full/file.txt</span></span>
<span class="line"><span>$ rmdir full</span></span>
<span class="line"><span>rmdir: failed to remove &#39;full/&#39;: Directory not empty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ mkdir empty</span></span>
<span class="line"><span>$ rmdir empty</span></span></code></pre></div><h3 id="更好的删除方式" tabindex="-1">更好的删除方式 <a class="header-anchor" href="#更好的删除方式" aria-label="Permalink to 更好的删除方式">​</a></h3>`,18)),i("p",null,[e[1]||(e[1]=a("此外还有一些并没有默认安装在终端上的 ")),n(s,{href:"https://www.redhat.com/sysadmin/recover-file-deletion-linux"},{default:t(()=>e[0]||(e[0]=[a("删除文件命令")])),_:1}),e[2]||(e[2]=a("，你可以从软件库安装它们。这些命令管理和使用的 ")),e[3]||(e[3]=i("code",null,"Trash",-1)),e[4]||(e[4]=a(" 文件夹与你在桌面模式使用的是同一个（而非你自己单独创建的），从而使删除文件变得更加方便。"))]),e[21]||(e[21]=l(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ trash ~/example.txt</span></span>
<span class="line"><span>$ trash --list</span></span>
<span class="line"><span>example.txt</span></span>
<span class="line"><span>$ trash --empty</span></span></code></pre></div><hr>`,2)),i("p",null,[e[6]||(e[6]=a("via: ")),n(s,{href:"https://opensource.com/article/21/8/remove-files-linux-terminal"},{default:t(()=>e[5]||(e[5]=[a("https://opensource.com/article/21/8/remove-files-linux-terminal")])),_:1})]),i("p",null,[e[11]||(e[11]=a("作者：")),n(s,{href:"https://opensource.com/users/seth"},{default:t(()=>e[7]||(e[7]=[a("Seth Kenlon")])),_:1}),e[12]||(e[12]=a(" 选题：")),n(s,{href:"https://github.com/lujun9972"},{default:t(()=>e[8]||(e[8]=[a("lujun9972")])),_:1}),e[13]||(e[13]=a(" 译者：")),n(s,{href:"https://github.com/unigeorge"},{default:t(()=>e[9]||(e[9]=[a("unigeorge")])),_:1}),e[14]||(e[14]=a(" 校对：")),n(s,{href:"https://github.com/wxy"},{default:t(()=>e[10]||(e[10]=[a("wxy")])),_:1})]),i("p",null,[e[17]||(e[17]=a("本文由 ")),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>e[15]||(e[15]=[a("LCTT")])),_:1}),e[18]||(e[18]=a(" 原创编译，")),n(s,{href:"https://linux.cn/"},{default:t(()=>e[16]||(e[16]=[a("Linux中国")])),_:1}),e[19]||(e[19]=a(" 荣誉推出"))])])}const k=p(u,[["render",m]]);export{v as __pageData,k as default};
